def calc(expr):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(expr[i:j])
            i = j
        elif c in '+-*/()':
            tokens.append(c)
            i += 1
        else:
            raise ValueError(f"Unexpected character: {c}")

    pos = 0

    def peek():
        nonlocal pos
        if pos < len(tokens):
            return tokens[pos]
        return None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_primary():
        tok = peek()
        if tok == '(':
            advance()
            val = parse_expr()
            if peek() != ')':
                raise ValueError("Expected ')'")
            advance()
            return val
        elif tok is not None and tok.isdigit():
            advance()
            return int(tok)
        else:
            raise ValueError(f"Unexpected token: {tok}")

    def parse_factor():
        neg = False
        while peek() == '-':
            advance()
            neg = not neg
        val = parse_primary()
        if neg:
            val = -val
        return val

    def int_div(a, b):
        # truncate toward zero
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    def parse_term():
        val = parse_factor()
        while peek() in ('*', '/'):
            op = advance()
            rhs = parse_factor()
            if op == '*':
                val = val * rhs
            else:
                val = int_div(val, rhs)
        return val

    def parse_expr():
        val = parse_term()
        while peek() in ('+', '-'):
            op = advance()
            rhs = parse_term()
            if op == '+':
                val = val + rhs
            else:
                val = val - rhs
        return val

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected trailing tokens")
    return result

